typedef float rational_t;
typedef unsigned int u_int;

class stringx { char *chars; void *my_buf; };
class color {
public:
  rational_t r, g, b, a;
  color() {}
  color(float _r,float _g,float _b,float _a=1.0F) : r(_r), g(_g), b(_b), a(_a) {}
};
class matrix4x4 { public: float m[4][4]; } __attribute__((aligned(16)));
class nglVector { public: float x, y, z, w; } __attribute__((aligned(16)));
class nglMatrix { public: nglVector x, y, z, w; } __attribute__((aligned(16)));
class nglMesh;
class nglLightContext;
struct nglRenderParams {
  u_int Flags;
  u_int TextureFrame;
  float ScrollU, ScrollV;
  nglVector TintColor;
  nglVector Scale;
  u_int MaterialMask;
  float ZBias;
  nglLightContext* LightContext;
  u_int NBones;
  nglMatrix* Bones;
};
struct list_layout { void *start, *finish, *end; };
struct rectf { float x0, y0, x1, y1; };

class widget {
public:
  enum widget_type_e { WTYPE_Bitmap, WTYPE_Text, WTYPE_TextBlock, WTYPE_Vrep };
  enum widget_state_e { WSTATE_None, WSTATE_Show, WSTATE_Hide };
  virtual ~widget();
  virtual void show();
  virtual void hide();
  virtual void ignore_parent();
  virtual void obey_parent();
  virtual void ignore_parent_showing();
  virtual void obey_parent_showing();
  virtual void frame_advance(rational_t);
  virtual void render();
  virtual void message_handler(unsigned int, unsigned int = 0, rational_t = 0, rational_t = 0);
  virtual void add_child(widget *);
  virtual void flush();
  bool is_shown() const { return (flags & 1); }
  virtual void move_to(short, short);
  virtual void move_to(rational_t, rational_t, short, short);
  virtual void scale_to(rational_t, rational_t);
  virtual void scale_to(rational_t, rational_t, rational_t, rational_t);
  virtual void rotate_to(rational_t);
  virtual void rotate_to(rational_t, rational_t, rational_t);
  virtual void set_color(color);
  virtual void set_color(color[4]);
  virtual void set_color(rational_t, rational_t, color);
  virtual void set_color(rational_t, rational_t, rational_t);
  virtual void fade_to(rational_t);
  virtual void fade_to(rational_t, rational_t, rational_t);
  virtual void set_subrect(int,int,int,int);
  virtual void set_origin(short,short);
  virtual void transform(rational_t v[2], color &c, int index);
  virtual rational_t get_width();
  virtual rational_t get_height();
  virtual void set_layer(int);
  virtual void update_pos();
  virtual void update_scale();
  virtual void update_rot();
  virtual void update_col();
protected:
  stringx widget_name;
  widget_type_e type;
  widget *parent;
  list_layout children;
  unsigned int flags;
  list_layout wevent_run_list;
  bool linear_animation;
  bool use_proj_matrix;
  widget_state_e next_state;
  rational_t state_wait_time;
  short x, y, abs_x, abs_y, base_x, base_y, orig_x, orig_y;
  rational_t angle, abs_angle, base_angle;
  rational_t R[2][2];
  color col[4], abs_col[4], base_col[4];
  rational_t S[2], abs_S[2], base_S[2];
  rectf subrect;
};

class vrep_widget : public widget {
public:
  virtual ~vrep_widget();
  virtual void show();
  virtual void frame_advance(rational_t);
  virtual void render();
protected:
  nglMesh *mesh;
  rational_t screen_radius;
  float axis[3];
  rational_t ax, ay, az, rps;
  rational_t rhw_midpoint, z, rhw_half_range;
  matrix4x4 rot_matrix;
  matrix4x4 mat;
  matrix4x4 special_w_xform;
  rational_t largest_z;
};

extern rational_t farzzz;
extern rational_t nearzzz;
extern void nglGetMatrix(nglMatrix &, u_int);
extern void nglGetProjectionParams(float *, float *, float *, float *, float *);
extern void ksnglSetOrthoMatrix(float, float, float, float, float = 0.0f, float = 1.0f);
extern void nglMulMatrix(nglMatrix &, const nglMatrix &, const nglMatrix &);
extern void nglListAddMesh(nglMesh *, const nglMatrix &, nglRenderParams * = 0);
extern void nglSetPerspectiveMatrix(float, float, float, float, float, float = 0.0f, float = 1.0f, int = 0, int = 0);
inline const nglMatrix &native_to_ngl(const matrix4x4 &m) { return *(const nglMatrix *)&m; }

void vrep_widget::render()
{
  if ( !is_shown() )
    return;

  if ( mesh )
  {
    nglMatrix nglViewToScreen;
    nglGetMatrix (nglViewToScreen, 1);

    nglMatrix m;
    nglRenderParams p;

    float hfov, cx, cy, nearz, farz;
    nglGetProjectionParams( &hfov, &cx, &cy, &nearz, &farz );

    color cl = color(1.0f, 1.0f, 1.0f, 1.0f);
    rational_t v[2] = { 0.0f, 0.0f };
    transform(v, cl, 0);

    ksnglSetOrthoMatrix( v[0], v[1], nearzzz, farzzz );

    nglMulMatrix( m, nglViewToScreen, native_to_ngl( mat ) );

    nglListAddMesh( mesh, m, &p );

    nglSetPerspectiveMatrix( hfov, cx, cy, nearz, farz );
  }
}
